package com.fintrack.khmtomnenh.rfq.controller; import com.fintrack.khmtomnenh.auth.entity.Auth; import com.fintrack.khmtomnenh.rfq.dto.RfqDto; import com.fintrack.khmtomnenh.rfq.entity.Rfq; import com.fintrack.khmtomnenh.rfq.service.RfqService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/rfqs") @RequiredArgsConstructor public class RfqController {private final RfqService s;@PostMapping @PreAuthorize("hasRole('BUYER')") public ResponseEntity<Rfq> create(@Valid @RequestBody RfqDto d,@AuthenticationPrincipal Auth a){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(d,a));}@GetMapping("/mine") @PreAuthorize("hasRole('BUYER')") public List<Rfq> mine(@AuthenticationPrincipal Auth a){return s.mine(a);}@GetMapping("/open") @PreAuthorize("hasRole('SUPPLIER')") public List<Rfq> open(){return s.open();}@GetMapping("/{id}") public Rfq get(@PathVariable Long id){return s.get(id);}}
